import os
import torch


class Config:
    """
    Central configuration for the Hindi/Tamil Question Answering Task.
    Includes paths, model hyperparameters, and training settings.
    """

    # =========================================================================
    # PATHS
    # =========================================================================

    # Input Metadata (generated by previous steps)
    METADATA_DIR = "./metadata"
    TRAIN_META_PATH = os.path.join(METADATA_DIR, "train.csv")
    VAL_META_PATH = os.path.join(METADATA_DIR, "val.csv")
    TEST_META_PATH = os.path.join(METADATA_DIR, "test.csv")

    # Working Directory for this specific idea/experiment
    WORKING_DIR = "./working/idea_5"

    # Cache Directories for processed data
    # We separate QA cache and TAPT cache
    QA_CACHE_DIR = os.path.join(WORKING_DIR, "qa_cache")
    TAPT_CACHE_DIR = os.path.join(WORKING_DIR, "tapt_cache")

    # Model Output Directories
    QA_MODEL_DIR = os.path.join(WORKING_DIR, "qa_models")
    TAPT_MODEL_DIR = os.path.join(WORKING_DIR, "tapt_model_finetuned")

    # Submission
    SUBMISSION_DIR = "./submission"
    SUBMISSION_PATH = os.path.join(SUBMISSION_DIR, "submission.csv")

    # =========================================================================
    # MODEL ARCHITECTURE & TOKENIZER
    # =========================================================================

    # Base model to be used (Multilingual)
    BASE_MODEL_NAME = "xlm-roberta-base"

    # Sliding Window Parameters
    MAX_LENGTH = 384
    DOC_STRIDE = 128

    # Labeling Strategy
    # Using Soft Overlap (Token Classification with B-ANS, I-ANS, O)
    NUM_LABELS = 3

    # =========================================================================
    # TRAINING HYPERPARAMETERS (QA FINE-TUNING)
    # =========================================================================

    # Batch size of 8 as per "Update Frequency" lesson
    TRAIN_BATCH_SIZE = 8
    EVAL_BATCH_SIZE = 16  # Can be larger for inference/eval

    LEARNING_RATE = 2e-5
    WEIGHT_DECAY = 0.01

    # Training duration
    NUM_EPOCHS = 10

    # Ensembling Seeds
    SEEDS = [42, 43, 44]

    # =========================================================================
    # TAPT HYPERPARAMETERS (TASK-ADAPTIVE PRETRAINING)
    # =========================================================================

    TAPT_BATCH_SIZE = 8
    TAPT_LEARNING_RATE = 2e-5
    TAPT_EPOCHS = 10  # Sufficient for adaptation on small corpus
    MLM_PROBABILITY = 0.15

    # =========================================================================
    # HARDWARE & UTILS
    # =========================================================================

    DEVICE = "cuda" if torch.cuda.is_available() else "cpu"
    NUM_WORKERS = 2

    @classmethod
    def setup(cls):
        """
        Creates the necessary directory structure for the experiment.
        """
        directories = [
            cls.WORKING_DIR,
            cls.QA_CACHE_DIR,
            cls.TAPT_CACHE_DIR,
            cls.QA_MODEL_DIR,
            cls.TAPT_MODEL_DIR,
            cls.SUBMISSION_DIR,
        ]

        for directory in directories:
            os.makedirs(directory, exist_ok=True)

        print(f"Configuration setup complete. Working directory: {cls.WORKING_DIR}")


# Automatically setup directories when imported, or can be called explicitly
Config.setup()
